let openMenuId = null;

document.querySelectorAll('.menu-item').forEach(item => {
    item.addEventListener('mousedown', (e) => {
        e.stopPropagation();
        const menuName = item.dataset.menu;
        const dd = item.querySelector('.menu-dropdown');
        if (!dd) return;
        if (dd.classList.contains('show')) {
            closeMenus();
        } else {
            closeMenus();
            dd.classList.add('show');
            item.classList.add('menu-open');
            openMenuId = menuName;
        }
    });
    item.addEventListener('mouseenter', () => {
        if (openMenuId && item.dataset.menu !== openMenuId) {
            closeMenus();
            const dd = item.querySelector('.menu-dropdown');
            if (dd) {
                dd.classList.add('show');
                item.classList.add('menu-open');
                openMenuId = item.dataset.menu;
            }
        }
    });
});

document.querySelectorAll('.menu-dd-item:not(.disabled)').forEach(item => {
    item.addEventListener('mousedown', (e) => {
        e.stopPropagation();
        if (!item.hasAttribute('data-sfx')) MacSFX.play('click', 0.3);
    });
});

