/* Pico Park menu sprite animator */
(function() {
    const canvas = document.getElementById('menu-sprite');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const SHEET_COLS = 11, SHEET_ROWS = 2;
    const FRAME_W = 80, FRAME_H = 98, PAD = 4;
    const DISPLAY_H = 16, SCALE = DISPLAY_H / FRAME_H;
    const DISPLAY_W = Math.round(FRAME_W * SCALE);
    const WALK_FRAMES = [2, 3, 4, 5];
    const WALK_SPF = 0.12;
    const JUMP_FRAME = 5, JUMP_HEIGHT = 6, JUMP_DUR = 0.4;

    /* DPR setup */
    const dpr = window.devicePixelRatio || 1;
    canvas.width = DISPLAY_W * dpr;
    canvas.height = DISPLAY_H * dpr;
    canvas.style.width = DISPLAY_W + 'px';
    canvas.style.height = DISPLAY_H + 'px';
    ctx.scale(dpr, dpr);

    const sheet = new Image();
    sheet.src = 'sprite.png';

    let walkTimer = 0, walkIdx = 0;
    let jumping = false, jumpTimer = 0;
    let lastTime = 0, paused = false;

    // The menu-bar walker doubles as a "this is YOU" indicator: tint it to the
    // signed-in student's saved hue -- the SAME shared roster sprite_hue the
    // Live Classroom board and the cr quiz render. If the walker is your color,
    // username/hue storage is loading correctly. hue 0 = no rotation = base.
    let hue = 0, hueTimer = 0;
    function _readSpriteHue() {
        try {
            const rc = (window.rosterClient && typeof window.rosterClient.current === 'function')
                ? window.rosterClient.current() : null;
            return (rc && typeof rc.spriteHue === 'number') ? rc.spriteHue : 0;
        } catch (_) { return 0; }
    }
    hue = _readSpriteHue();

    function getFrameXY(idx) {
        const col = idx % SHEET_COLS;
        const row = Math.floor(idx / SHEET_COLS);
        return { x: col * (FRAME_W + PAD), y: row * (FRAME_H + PAD) };
    }

    function draw(frameIdx) {
        ctx.clearRect(0, 0, DISPLAY_W, DISPLAY_H);
        if (!sheet.complete) return;
        const f = getFrameXY(frameIdx);
        // Tint to your saved hue (same hue-rotate the board + quiz use). filter
        // is set right before the draw and cleared right after so clearRect and
        // the jump transform are unaffected. hue 0 -> 'none' = the base sprite.
        ctx.filter = hue ? ('hue-rotate(' + hue + 'deg)') : 'none';
        ctx.drawImage(sheet, f.x, f.y, FRAME_W, FRAME_H, 0, 0, DISPLAY_W, DISPLAY_H);
        ctx.filter = 'none';
    }

    function tick(now) {
        if (!lastTime) lastTime = now;
        const dt = Math.min((now - lastTime) / 1000, 0.1);
        lastTime = now;

        if (paused) { requestAnimationFrame(tick); return; }

        // The walker lives in the classic menu bar, which the Pico skin hides. Draw nothing
        // there and look again twice a second, so a skin switch brings it back.
        if (document.documentElement.classList.contains('pico-home')) {
            lastTime = 0;
            setTimeout(function () { requestAnimationFrame(tick); }, 500);
            return;
        }

        // Refresh the hue ~once a second so a sign-in (or hue change) after the
        // page loaded recolors the walker without a reload -- cheap, throttled.
        hueTimer += dt;
        if (hueTimer >= 1) { hueTimer = 0; hue = _readSpriteHue(); }

        let frameIdx;
        if (jumping) {
            jumpTimer += dt;
            if (jumpTimer >= JUMP_DUR) {
                jumping = false;
                jumpTimer = 0;
                canvas.style.transform = '';
            } else {
                const t = jumpTimer / JUMP_DUR;
                const yOff = Math.sin(t * Math.PI) * JUMP_HEIGHT;
                canvas.style.transform = 'translateY(-' + yOff + 'px)';
            }
            frameIdx = JUMP_FRAME;
        } else {
            walkTimer += dt;
            if (walkTimer >= WALK_SPF) {
                walkTimer -= WALK_SPF;
                walkIdx = (walkIdx + 1) % WALK_FRAMES.length;
            }
            frameIdx = WALK_FRAMES[walkIdx];
        }

        draw(frameIdx);
        requestAnimationFrame(tick);
    }

    sheet.onload = function() { requestAnimationFrame(tick); };

    document.addEventListener('visibilitychange', function() {
        paused = document.hidden;
        if (!paused) lastTime = 0;
    });

    canvas.addEventListener('click', function(e) {
        e.stopPropagation();
        closeMenus();
        if (!jumping) { jumping = true; jumpTimer = 0; MacSFX.play('laugh', 0.5); }
    });
})();

function closeMenus() {
    document.querySelectorAll('.menu-dropdown').forEach(m => m.classList.remove('show'));
    document.querySelectorAll('.menu-item').forEach(m => m.classList.remove('menu-open'));
    openMenuId = null;
}
// Menu polish (2026-08-20): every item does something. Check-marks reflect live state.
function _renderMenuChecks() {
    var sound = document.getElementById('menu-sound-toggle');
    if (sound) {
        var muted = !!(typeof MacSFX !== 'undefined' && MacSFX.muted);
        sound.textContent = (muted ? '\u2003' : '\u2713') + ' Sound';
    }
    var quiet = document.getElementById('menu-sound-quiet');
    if (quiet) quiet.textContent = (_sfxIsQuiet() ? '\u2713' : '\u2003') + ' Quieter';
    var lowPower = document.getElementById('menu-sound-lowpower');
    if (lowPower) {
        var setting = _sfxLowPowerSetting();
        lowPower.textContent = '\u2003 Low-power sound: ' + setting.charAt(0).toUpperCase() + setting.slice(1);
    }
}
// The per-device "quieter" level (SFX_SPEC \u00a71: localStorage apstats-sfx-level, applied on the
// engine's master). The Sound option stays the on/off switch.
function _sfxIsQuiet() {
    try { return !!(window.sfx && window.sfx.getLevel() === 'quiet'); } catch (_) { return false; }
}
function _toggleSfxQuiet() {
    try { if (window.sfx) window.sfx.setLevel(_sfxIsQuiet() ? 'normal' : 'quiet'); } catch (_) {}
    try { _renderMenuChecks(); } catch (_) {}
}
// Low-power sound (handoff/audio/AUDIO_IDEAS_HANDOFF.md section 0): auto -> on -> off -> auto.
// Auto = the engine's detection (<= 4 cores, <= 4 GB, or slow frames). Stored per device in
// localStorage apstats-sfx-lowpower.
var SFX_LOW_POWER_NEXT = { auto: 'on', on: 'off', off: 'auto' };
function _sfxLowPowerSetting() {
    try { return window.sfx ? window.sfx.getLowPower() : 'auto'; } catch (_) { return 'auto'; }
}
function _cycleSfxLowPower() {
    try { if (window.sfx) window.sfx.setLowPower(SFX_LOW_POWER_NEXT[_sfxLowPowerSetting()] || 'auto'); } catch (_) {}
    try { _renderMenuChecks(); } catch (_) {}
}
// Default level by role: students start at "quiet" (a room of 25 devices), teachers at "normal".
// Once the role is known (signed in) the default is stored, so it persists on this device; a
// level the user picked is never overwritten.
function _sfxApplyRoleDefault(who, isTeacher) {
    if (!window.sfx) return;
    var level = isTeacher ? 'normal' : 'quiet';
    window.sfx.setDefaultLevel(level);
    if (who && !window.sfx.hasStoredLevel()) window.sfx.setLevel(level);
}
try {
    window._toggleSfxQuiet = _toggleSfxQuiet; window._sfxIsQuiet = _sfxIsQuiet;
    window._cycleSfxLowPower = _cycleSfxLowPower; window._sfxLowPowerSetting = _sfxLowPowerSetting;
} catch (_) {}
function _menuShowDoNow() {
    var card = document.getElementById('donow-card');
    if (!card || card.style.display === 'none') { openSignInModal(); return; }
    try { card.scrollIntoView({ behavior: 'smooth', block: 'center' }); } catch (_) { card.scrollIntoView(); }
    card.classList.add('donow-flash');
    setTimeout(function () { card.classList.remove('donow-flash'); }, 1600);
}
function _menuAbout() {
    var build = (typeof APP_BUILD === 'string') ? APP_BUILD : '';
    var who = null;
    try { who = (window.rosterClient && rosterClient.current && rosterClient.current()) || null; } catch (_) {}
    showDialog('\uD83D\uDDA5\uFE0F',
        'AP Statistics Desk \u2014 build ' + build
        + (who ? '\nSigned in as ' + who.username : '\nNot signed in')
        + '\nIf something looks wrong, tell the teacher the build number.',
        'OK');
}
// Esc closes any open menu; the menus are mouse/touch driven otherwise.
document.addEventListener('keydown', function (e) { if (e.key === 'Escape' && openMenuId) closeMenus(); });

