/* ── Draggable Desktop Icons + Auto-Arrange by Usage ── */
(function() {
    var icons = Array.from(document.querySelectorAll('.app-icon'));
    var dragIcon = null, startX = 0, startY = 0, origX = 0, origY = 0, didDrag = false;
    var ICON_TOP_START = 36;
    var ICON_GAP = 72;
    var ICON_RIGHT = 20;

    function getUsageCounts() {
        try { return JSON.parse(localStorage.getItem('ap-roadmap-icon-usage') || '{}'); }
        catch(e) { return {}; }
    }

    // Sort icons by usage count (descending), arrange in right column
    function arrangeByUsage() {
        var counts = getUsageCounts();
        icons.sort(function(a, b) {
            return (counts[b.dataset.app] || 0) - (counts[a.dataset.app] || 0);
        });
        // Hidden icons (e.g. the teacher-only Teacher Inbox for a student) take no slot.
        var visible = icons.filter(function(el) { return el.style.display !== 'none'; });
        visible.forEach(function(el, i) {
            el.style.top = (ICON_TOP_START + i * ICON_GAP) + 'px';
            el.style.right = ICON_RIGHT + 'px';
            el.style.left = 'auto';
            el.style.bottom = 'auto';
        });
    }

    icons.forEach(function(el) {
        el.addEventListener('mousedown', function(e) {
            if (e.button !== 0) return;
            dragIcon = el;
            didDrag = false;
            var rect = el.getBoundingClientRect();
            origX = rect.left;
            origY = rect.top;
            startX = e.clientX;
            startY = e.clientY;
            el.style.left = origX + 'px';
            el.style.top = origY + 'px';
            el.style.right = 'auto';
            el.style.bottom = 'auto';
            e.preventDefault();
        });
    });

    document.addEventListener('mousemove', function(e) {
        if (!dragIcon) return;
        var dx = e.clientX - startX;
        var dy = e.clientY - startY;
        if (!didDrag && Math.abs(dx) < 4 && Math.abs(dy) < 4) return;
        didDrag = true;
        dragIcon.classList.add('dragging');
        dragIcon.style.left = (origX + dx) + 'px';
        dragIcon.style.top = (origY + dy) + 'px';
    });

    document.addEventListener('mouseup', function() {
        if (!dragIcon) return;
        dragIcon.classList.remove('dragging');
        dragIcon = null;
    });

    // Suppress click/dblclick if we just dragged
    document.addEventListener('click', function(e) {
        if (didDrag) { e.stopPropagation(); didDrag = false; }
    }, true);

    arrangeByUsage();
    // Re-run when a role change shows/hides a teacher-only icon (Teacher Inbox).
    window._arrangeDesktopIcons = arrangeByUsage;
})();

// Click backdrop to close app overlays
document.querySelectorAll('.app-overlay').forEach(function(overlay) {
    overlay.addEventListener('click', function(e) {
        if (e.target === overlay) {
            var id = overlay.id.replace('app-', '').replace('-overlay', '');
            destroyApp(id);
        }
    });
});

// Draggable app windows (by title bar)
(function() {
    var dragWin = null, startX = 0, startY = 0, origX = 0, origY = 0;

    document.querySelectorAll('.app-window .game-title-bar').forEach(function(tb) {
        tb.style.cursor = 'grab';

        // Double-click title bar to maximize/restore
        tb.addEventListener('dblclick', function(e) {
            if (e.target.classList.contains('close-box') || e.target.classList.contains('collapse-box')) return;
            var overlay = tb.closest('.app-overlay');
            if (!overlay) return;
            var id = overlay.id.replace('app-', '').replace('-overlay', '');
            toggleMaximize(id);
        });

        tb.addEventListener('mousedown', function(e) {
            if (e.target.classList.contains('close-box') || e.target.classList.contains('collapse-box')) return;
            var win = tb.closest('.app-window');
            if (win.classList.contains('maximized')) return; // Don't drag when maximized
            dragWin = win;
            // Convert from centered to positioned
            var rect = win.getBoundingClientRect();
            win.style.left = rect.left + 'px';
            win.style.top = rect.top + 'px';
            win.style.transform = 'none';
            startX = e.clientX;
            startY = e.clientY;
            origX = rect.left;
            origY = rect.top;
            tb.style.cursor = 'grabbing';
            e.preventDefault();
        });
    });

    document.addEventListener('mousemove', function(e) {
        if (!dragWin) return;
        dragWin.style.left = (origX + e.clientX - startX) + 'px';
        dragWin.style.top = (origY + e.clientY - startY) + 'px';
    });

    document.addEventListener('mouseup', function() {
        if (!dragWin) return;
        var tb = dragWin.querySelector('.game-title-bar');
        if (tb) tb.style.cursor = 'grab';
        dragWin = null;
    });
})();


/* ═══ Desktop multitasking: click-to-focus + icon right-click menu ═══ */
var _appTopZ = 260;
(function() {
    // Click-to-focus: clicking anywhere in an app window raises it above the
    // other open windows (capture phase so it runs even when a child handler
    // stops propagation). Cross-origin iframes don't bubble mousedown to us, so
    // raising those is done via their title bar — which is enough.
    document.addEventListener('mousedown', function(e) {
        var win = (e.target && e.target.closest) ? e.target.closest('.app-window') : null;
        if (!win) return;
        var ov = win.closest('.app-overlay');
        if (ov) ov.style.zIndex = ++_appTopZ;
    }, true);

    // Right-click an app icon → Open / Open in new tab (iframe apps only).
    function _deskLaunch(id) {
        if (id === 'wallet') { if (typeof openWallet === 'function') openWallet(); return; }
        if (id === 'game')   { if (typeof openGame === 'function') openGame(); return; }
        if (typeof openApp === 'function') openApp(id);
    }
    function _deskAppUrl(id) {
        try { return (typeof APP_REGISTRY !== 'undefined' && APP_REGISTRY[id]) ? APP_REGISTRY[id].url : null; }
        catch (_) { return null; }
    }

    var _iconMenu = null;
    function _closeIconMenu() {
        if (_iconMenu) { _iconMenu.remove(); _iconMenu = null; }
        document.removeEventListener('mousedown', _onDocDown, true);
        document.removeEventListener('keydown', _onKey, true);
        window.removeEventListener('scroll', _closeIconMenu, true);
    }
    function _onDocDown(e) { if (_iconMenu && !_iconMenu.contains(e.target)) _closeIconMenu(); }
    function _onKey(e) { if (e.key === 'Escape') _closeIconMenu(); }

    function _showIconMenu(x, y, id) {
        _closeIconMenu();
        var labelEl = document.querySelector('.app-icon[data-app="' + id + '"] .icon-label');
        var label = labelEl ? (labelEl.textContent || '') : '';
        var url = _deskAppUrl(id);

        var menu = document.createElement('div');
        menu.className = 'chicago';
        menu.style.cssText = 'position:fixed;z-index:20000;min-width:160px;background:#fff;'
            + 'border:1px solid #000;box-shadow:2px 2px 0 rgba(0,0,0,0.4);padding:2px 0;'
            + 'font-size:12px;cursor:default;user-select:none';

        var items = [{ txt: '🗂 Open' + (label ? ' ' + label : ''), fn: function() { _deskLaunch(id); } }];
        if (url) items.push({ txt: '↗ Open in new tab', fn: function() { try { window.open(url, '_blank', 'noopener'); } catch (_) {} } });

        items.forEach(function(it) {
            var d = document.createElement('div');
            d.textContent = it.txt;
            d.style.cssText = 'padding:4px 16px;white-space:nowrap';
            d.onmouseenter = function() { d.style.background = '#000'; d.style.color = '#fff'; };
            d.onmouseleave = function() { d.style.background = ''; d.style.color = ''; };
            d.onclick = function() { _closeIconMenu(); it.fn(); };
            menu.appendChild(d);
        });

        document.body.appendChild(menu);
        var r = menu.getBoundingClientRect();
        menu.style.left = Math.max(4, Math.min(x, window.innerWidth - r.width - 6)) + 'px';
        menu.style.top = Math.max(4, Math.min(y, window.innerHeight - r.height - 6)) + 'px';
        _iconMenu = menu;
        setTimeout(function() {
            document.addEventListener('mousedown', _onDocDown, true);
            document.addEventListener('keydown', _onKey, true);
            window.addEventListener('scroll', _closeIconMenu, true);
        }, 0);
    }

    document.querySelectorAll('.app-icon').forEach(function(icon) {
        icon.addEventListener('contextmenu', function(e) {
            var id = icon.getAttribute('data-app');
            if (!id) return;
            e.preventDefault();
            _showIconMenu(e.clientX, e.clientY, id);
        });
    });
})();


/* ═══ DESK ROSTER — resolve online usernames to real student names ═══ */
/* Feeds the "Online Now" list so any avatar is traceable. Teachers get the
   full roster (/roster/list); students get their section + the universal
   PeriodX section (reusing the cached _fetchSectionRoster). Unknown auto-
   generated "Player####" names (the signed-out fallback) are flagged guests. */
const DeskRoster = {
    map: {},            // lowercased username -> realName
    loaded: false,
    _loading: null,
    load(force) {
        if (this._loading) return this._loading;
        if (this.loaded && !force) return Promise.resolve(this.map);
        this._loading = (async () => {
            const m = {};
            try {
                const who = (window.rosterClient && window.rosterClient.current && window.rosterClient.current()) || null;
                const base = (typeof window !== 'undefined' && window.ROSTER_SERVICE_URL) || null;
                const token = (window.rosterClient && window.rosterClient.token && window.rosterClient.token()) || null;
                let students = [];
                if (base && token && who && who.role === 'teacher') {
                    try {
                        const res = await fetch(base + '/roster/list', { headers: { 'Authorization': 'Bearer ' + token } });
                        if (res.ok) { const d = await res.json(); if (d && Array.isArray(d.students)) students = d.students; }
                    } catch (_) {}
                }
                if (students.length === 0 && typeof _fetchSectionRoster === 'function') {
                    // Teacher decision 2026-10-06: no barriers between Period B and Period E — resolve
                    // real names for BOTH periods (+ the teacher's PeriodX), not just the viewer's own.
                    const sections = [];
                    if (who && who.section) sections.push(who.section);
                    ['PeriodB', 'PeriodE', 'PeriodX'].forEach(s => { if (!sections.includes(s)) sections.push(s); });
                    for (const s of sections) {
                        try { const arr = await _fetchSectionRoster(s); (arr || []).forEach(x => students.push(x)); } catch (_) {}
                    }
                }
                students.forEach(s => {
                    if (s && s.username && s.realName) m[String(s.username).trim().toLowerCase()] = String(s.realName).trim();
                });
                if (who && who.username && who.realName) m[String(who.username).trim().toLowerCase()] = String(who.realName).trim();
            } catch (_) {}
            this.map = m; this.loaded = true; this._loading = null;
            return m;
        })();
        return this._loading;
    },
    realName(u) { return this.map[String(u == null ? '' : u).trim().toLowerCase()] || ''; },
    // Signed-out identities: the stable "Guest_…" identity, or legacy "Player####".
    isGuest(u) { var s = String(u == null ? '' : u).trim(); return !this.realName(u) && (/^guest_/i.test(s) || /^player\d+$/i.test(s)); }
};
function _deskEsc(s){ return String(s==null?'':s).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }

function _isTeacher() {
    try {
        var who = (window.rosterClient && rosterClient.current && rosterClient.current()) || null;
        return !!(who && who.role === 'teacher');
    } catch (e) { return false; }
}

/* Teacher-only: show a QR of the cr scan-to-verify tool so the teacher can open
   it on their PHONE (where the camera scan is natural) and verify a student's
   printed summary / receipt QR. The phone gets VERIFICATION; the live-gradebook
   cross-check is teacher-token-gated (sign in on the phone, or use this device)
   — we deliberately do NOT bridge the teacher token through the QR, since that
   would leak teacher access to anyone who photographs the code. */
function openVerifyQR() {
    var url = 'https://robjohncolson.github.io/curriculum_render/teacher-verify.html';
    // Pre-fill the teacher username on the phone (a username is not a secret; the
    // teacher token is NEVER bridged). They type their password once on the phone.
    try {
        var _vqWho = (window.rosterClient && rosterClient.current) ? rosterClient.current() : null;
        if (_vqWho && _vqWho.username) url += '?u=' + encodeURIComponent(_vqWho.username);
    } catch (_) {}
    var panel = document.getElementById('verify-qr-overlay');
    if (!panel) {
        panel = document.createElement('div');
        panel.id = 'verify-qr-overlay';
        panel.style.cssText = 'position:fixed;inset:0;z-index:100000;background:rgba(0,0,0,.45);display:none;align-items:center;justify-content:center';
        panel.innerHTML = '<div id="verify-qr-card" style="background:#fff;color:#111;max-width:340px;width:90%;border:2px solid #000;border-radius:10px;box-shadow:0 12px 40px rgba(0,0,0,.4);padding:16px;font-family:Geneva,Verdana,sans-serif"></div>';
        panel.addEventListener('click', function(e){ if (e.target === panel) panel.style.display = 'none'; });
        document.body.appendChild(panel);
    }
    panel.style.display = 'flex';
    var card = document.getElementById('verify-qr-card');
    card.innerHTML =
        '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">'
        + '<strong style="font-size:16px">&#128269; Verify a Record</strong>'
        + '<button onclick="document.getElementById(\'verify-qr-overlay\').style.display=\'none\'" aria-label="Close" style="border:none;background:none;font-size:20px;cursor:pointer;line-height:1">&times;</button></div>'
        + '<p style="margin:0 0 8px;font-size:13px">Scan with your phone to open the verifier there, then point it at a student’s printed summary / receipt QR.</p>'
        + '<div id="verify-qr" style="display:flex;justify-content:center;margin:8px 0"></div>'
        + '<div style="text-align:center"><a href="' + _deskEsc(url) + '" target="_blank" rel="noopener" style="font-size:12px">Open on this device →</a></div>';
    var host = document.getElementById('verify-qr');
    host.innerHTML = '';
    if (typeof QRCode === 'function') {
        new QRCode(host, { text: url, width: 170, height: 170, correctLevel: QRCode.CorrectLevel && QRCode.CorrectLevel.L });
    } else {
        host.textContent = url;
    }
}
window.openVerifyQR = openVerifyQR;

/* ═══ PROGRESS LEDGER — proto-git sessions/commits view ═══ */
/* Fetches the signed, prev-chained commit history (GET /commits) and renders it
   as a session list; each commit can be flashed as a self-contained QR that
   verify.html#commit= can verify offline. */
function _ledgerB64url(str){ try { return btoa(unescape(encodeURIComponent(str))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,''); } catch(e){ return ''; } }
// Dense payload QRs (commit/guest/reconcile) are ~v16 at ECC-L — still too tight
// to scan at thumbnail size, and the QR lib draws no quiet zone. We use ECC-L
// (correctLevel.L) so the modules are as large as possible for a given payload,
// render them with a white quiet-zone, and make them tap-to-enlarge: the student
// taps, it fills the screen, you scan.
window._showBigQR = function(text){
    var ov = document.getElementById('big-qr-overlay');
    if (!ov) {
        ov = document.createElement('div');
        ov.id = 'big-qr-overlay';
        ov.style.cssText = 'position:fixed;inset:0;z-index:100002;background:rgba(0,0,0,.82);display:none;flex-direction:column;align-items:center;justify-content:center;cursor:pointer;padding:16px';
        ov.innerHTML = '<div style="background:#fff;padding:22px;border-radius:10px;display:flex;align-items:center;justify-content:center"><div id="big-qr-host"></div></div>'
            + '<div style="color:#fff;margin-top:14px;font-family:Geneva,Verdana,sans-serif;font-size:13px">tap anywhere to close</div>';
        ov.addEventListener('click', function(){ ov.style.display = 'none'; });
        document.body.appendChild(ov);
    }
    ov.style.display = 'flex';
    var host = document.getElementById('big-qr-host');
    host.innerHTML = '';
    var px = Math.max(240, Math.min(Math.min(window.innerWidth, window.innerHeight) - 110, 460));
    if (typeof QRCode === 'function') {
        try { new QRCode(host, { text: text, width: px, height: px, correctLevel: QRCode.CorrectLevel && QRCode.CorrectLevel.L }); }
        catch (e) { host.textContent = 'This code is too large for a single QR.'; }
    } else { host.textContent = 'QR library missing.'; }
};
// Small QR with a white quiet-zone, tappable to enlarge for scanning.
window._renderScanQR = function(host, text){
    if (!host) return;
    host.innerHTML = '';
    var box = document.createElement('div');
    box.style.cssText = 'background:#fff;padding:10px;border-radius:6px;display:inline-block;cursor:zoom-in';
    box.title = 'Tap to enlarge for scanning';
    host.appendChild(box);
    if (typeof QRCode === 'function') {
        try { new QRCode(box, { text: text, width: 168, height: 168, correctLevel: QRCode.CorrectLevel && QRCode.CorrectLevel.L }); }
        catch (e) { box.textContent = 'QR too large'; }
    } else { box.textContent = 'QR library missing'; }
    box.addEventListener('click', function(){ window._showBigQR(text); });
};
window._commitShowQR = function(btn){
    var host = btn.parentElement.querySelector('.commit-qr-host');
    if (!host) return;
    if (host.firstChild) { host.innerHTML = ''; return; } // toggle off
    var deep = btn.getAttribute('data-deep') || '';
    // The QR carries ONLY the signed manifest — tiny + reliably scannable. The
    // manifest's signed root already commits to every receipt; the full item-by-
    // item check is one tap away via the (larger) Verify link.
    var qrPayload = deep;
    try {
        var s = deep.replace(/-/g, '+').replace(/_/g, '/'); while (s.length % 4) s += '=';
        var obj = JSON.parse(decodeURIComponent(escape(atob(s))));
        if (obj && obj.m) qrPayload = obj.m; // manifest compact (payload.sig)
    } catch (e) {}
    var url = 'https://robjohncolson.github.io/curriculum_render/verify.html#commit=' + qrPayload;
    window._renderScanQR(host, url);
};
