// (they MUST stay in sync — a test pins build === APP_BUILD — or the nudge loops).
(function _wireUpdateNudge(){
  var nudged = false;
  function showBanner(){
    if (nudged || document.getElementById('update-nudge')) return;
    nudged = true;
    var bar = document.createElement('div');
    bar.id = 'update-nudge'; bar.className = 'chicago'; bar.setAttribute('role','status');
    var msg = document.createElement('span'); msg.textContent = '\u{1F504} A new version is available.';
    var reload = document.createElement('button'); reload.className = 's7btn s7btn-default'; reload.textContent = 'Reload';
    reload.addEventListener('click', function(){ try { location.reload(); } catch(_) { location.href = location.href; } });
    var dismiss = document.createElement('button'); dismiss.className = 's7btn'; dismiss.textContent = '×';
    dismiss.setAttribute('aria-label','Dismiss'); dismiss.addEventListener('click', function(){ bar.remove(); });
    bar.appendChild(msg); bar.appendChild(reload); bar.appendChild(dismiss);
    document.body.appendChild(bar);
  }
  function check(){
    if (nudged) return;
    try {
      fetch('version.json?_=' + Date.now(), { cache: 'no-store' })
        .then(function(r){ return r.ok ? r.json() : null; })
        .then(function(v){ if (v && v.build && v.build !== APP_BUILD) showBanner(); })
        .catch(function(){});
    } catch(_) {}
  }
  setTimeout(check, 8000);                 // initial, shortly after boot
  setInterval(check, 5 * 60 * 1000);       // every 5 min
  document.addEventListener('visibilitychange', function(){ if (!document.hidden) check(); });  // on tab refocus
})();

